<template><view class="page"><view v-if="item" class="card"><text class="title">{{item.prizeTitle}}</text><text>用户：{{item.studentName}} {{item.studentNo}}</text><text>文本核销码：{{item.redemptionCode || ('GKZH-' + item.lotteryRecordId)}}</text><text>状态：{{item.status==='1'?'已核销':'待核销'}}</text><text v-if="item.redeemTime">核销时间：{{formatDate(item.redeemTime)}}</text><button v-if="item.status==='0' && canRedeem" class="button" @click="redeem">确认核销</button></view></view></template>
<script>import {scanPrize,redeemPrize} from '@/api/staff.js';export default{data:()=>({item:null,recordId:null,canRedeem:Number((uni.getStorageSync('staffProfile')||{}).canRedeem)===1}),onLoad(o){this.recordId=o.recordId;scanPrize(o.recordId).then(r=>this.item=r.data).catch(e=>uni.showToast({title:e.message,icon:'none'}))},methods:{formatDate(v){if(!v)return '';const d=new Date(v);if(isNaN(d.getTime()))return String(v);const p=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())} ${p(d.getHours())}:${p(d.getMinutes())}:${p(d.getSeconds())}`},redeem(){if(!this.canRedeem)return;redeemPrize(this.recordId).then(r=>{this.item=r.data;uni.showToast({title:'核销成功',icon:'success'})}).catch(e=>uni.showToast({title:e.message,icon:'none'}))}}}</script>
<style scoped>.page{min-height:100vh;background:#f4f7fb;padding:40rpx 28rpx}.card{background:#fff;border-radius:22rpx;padding:38rpx;display:flex;flex-direction:column;gap:22rpx;color:#52657c}.title{font-size:38rpx;font-weight:700;color:#1a2c4a}.button{background:#2f80ed;color:#fff;border-radius:44rpx;margin-top:28rpx}</style>
